Here is the complete Terraform module using modern AWS provider and EKS module:

```hcl
terraform {
  required_version = ">= 1.6.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.45"
    }
    helm = {
      source  = "hashicorp/helm"
      version = "~> 2.13"
    }
  }
}

variable "cluster_name" {
  type    = string
  default = "nexus-ai-cluster"
}

variable "region" {
  type    = string
  default = "us-east-1"
}

# EKS Cluster
module "eks" {
  source  = "terraform-aws-modules/eks/aws"
  version = "~> 20.8"

  cluster_name    = var.cluster_name
  cluster_version = "1.29"

  cluster_endpoint_public_access  = true
  enable_cluster_creator_admin_permissions = true

  vpc_id     = module.vpc.vpc_id
  subnet_ids = module.vpc.private_subnets

  eks_managed_node_groups = {
    # System node group for monitoring, ingress, and core controllers
    system_nodes = {
      instance_types = ["m6i.xlarge"]
      min_size       = 2
      max_size       = 4
      desired_size   = 2
      labels = {
        role = "system"
      }
    }

    # GPU Worker group for vLLM & LLM inference workloads
    gpu_inference_nodes = {
      instance_types = ["g5.2xlarge"] # 1x NVIDIA A10G (24GB VRAM), 8 vCPU, 32GB RAM
      ami_type       = "AL2_x86_64_GPU"
      min_size       = 1
      max_size       = 5
      desired_size   = 2

      taints = {
        gpu = {
          key    = "nvidia.com/gpu"
          value  = "true"
          effect = "NO_SCHEDULE"
        }
      }

      labels = {
        "accelerator" = "nvidia-a10g"
        "workload"    = "inference"
      }

      block_device_mappings = {
        xvda = {
          device_name = "/dev/xvda"
          ebs = {
            volume_size           = 150 # Large disk for container images & model weights
            volume_type           = "gp3"
            iops                  = 3000
            throughput            = 125
            delete_on_termination = true
          }
        }
      }
    }
  }
}

# Install NVIDIA GPU Operator via Helm
resource "helm_release" "nvidia_gpu_operator" {
  name             = "gpu-operator"
  repository       = "https://helm.ngc.nvidia.com/nvidia"
  chart            = "gpu-operator"
  version          = "v23.9.2"
  namespace        = "gpu-operator"
  create_namespace = true

  set {
    name  = "operator.defaultRuntime"
    value = "containerd"
  }
  set {
    name  = "toolkit.enabled"
    value = "true"
  }

  depends_on = [module.eks]
}
```
